export default function App() {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [detailProduct, setDetailProduct] = useState<{product: any, category: string} | null>(null);

  const addToCart = (item: CartItem) => {
    setCart([...cart, item]);
  };

  const removeFromCart = (index: number) => {
    setCart(cart.filter((_, i) => i !== index));
  };

  const updateQuantity = (index: number, newQuantity: number) => {
    const newCart = [...cart];
    newCart[index].quantity = newQuantity;
    setCart(newCart);
  };

  const clearCart = () => setCart([]);

  const openProductDetail = (product: any, category: string) => {
    setDetailProduct({ product, category });
  };

  return (
    <CartContext.Provider value={{ 
      cart, 
      addToCart, 
      removeFromCart, 
      updateQuantity, 
      clearCart, 
      isCartOpen, 
      setIsCartOpen,
      openProductDetail
    }}>
      <HelmetProvider>
        <BrowserRouter>
          <ScrollToTop />
          <CanonicalLink />
          <div className="min-h-screen bg-[#f8fafc] font-sans text-secondary flex flex-col">
            <Navbar />

            <main className="flex-grow">
              <AppRoutes />
            </main>

            <Footer />
            <BackToTopButton />

            <CartDrawer />
            <ProductDetailModal 
              product={detailProduct?.product} 
              category={detailProduct?.category || ""} 
              isOpen={!!detailProduct} 
              onClose={() => setDetailProduct(null)}
              onAddToCart={addToCart}
            />
          </div>
        </BrowserRouter>
      </HelmetProvider>
    </CartContext.Provider>
  );
}

