// --- Helper for Search Normalization ---
const normalizeSearchText = (str: string) => {
  if (!str) return "";
  return str.toLowerCase()
    .replace(/ı/g, 'i')
    .replace(/ğ/g, 'g')
    .replace(/ü/g, 'u')
    .replace(/ş/g, 's')
    .replace(/ö/g, 'o')
    .replace(/ç/g, 'c')
    .replace(/(\d)\.(\d)/g, '$1$2') // 2.000 -> 2000
    .replace(/(\d)\s+(\d)/g, '$1$2') // 2 000 -> 2000
    .trim();
};

