const DynamicImageContainer = ({ 
  src, 
  alt, 
  title, 
  isTallLayoutDefault = false,
  className = "",
  imgClassName = "",
  isPriority = false
}: { 
  src: string; 
  alt: string; 
  title?: string; 
  isTallLayoutDefault?: boolean;
  className?: string;
  imgClassName?: string;
  isPriority?: boolean;
}) => {
  const [aspect, setAspect] = useState<'tall' | 'wide' | null>(null);

  return (
    <div className={`overflow-hidden rounded-xl bg-white mb-4 flex items-center justify-center p-1.5 w-fit mx-auto transition-all duration-300 ${
      aspect === 'tall' 
        ? 'h-[360px] md:h-[400px]' 
        : aspect === 'wide' 
          ? 'h-[230px] md:h-[270px]' 
          : isTallLayoutDefault 
            ? 'h-[360px] md:h-[400px]' 
            : 'h-[230px] md:h-[270px]'
    } ${className}`}>
      <img 
        src={src} 
        alt={alt} 
        title={title}
        loading={isPriority ? "eager" : "lazy"}
        fetchPriority={isPriority ? "high" : "auto"}
        decoding="async"
        width={1200}
        height={800}
        referrerPolicy="no-referrer"
        onLoad={(e) => {
          const img = e.currentTarget;
          if (img.naturalHeight > img.naturalWidth) {
            setAspect('tall');
          } else {
            setAspect('wide');
          }
        }}
        className={`h-full w-auto object-contain rounded-lg transition-all duration-300 ${imgClassName}`} 
      />
    </div>
  );
};

